<?php
namespace RobwForge;
defined('ABSPATH') || exit;
final class Hooks {
 static function local(){return defined('ROBW_FORGE_LOCAL_TEST')&&ROBW_FORGE_LOCAL_TEST&&in_array(wp_parse_url(home_url(),PHP_URL_HOST),['127.0.0.1','localhost'],true);}
 static function validate_url($url){if(!is_string($url)||strlen($url)>2048||preg_match('/[\x00-\x20\x7f]/',$url))throw new \InvalidArgumentException('Webhook URL');$u=wp_parse_url($url);if(!$u||empty($u['host'])||isset($u['user'])||isset($u['pass'])||isset($u['fragment']))throw new \InvalidArgumentException('Webhook URL');if(self::local()&&$u['scheme']==='http'&&$u['host']==='127.0.0.1')return$u;if(($u['scheme']??'')!=='https'||($u['port']??443)!==443||!preg_match('/^[a-zA-Z0-9.-]+$/D',$u['host']))throw new \InvalidArgumentException('HTTPS webhook required');if(filter_var($u['host'],FILTER_VALIDATE_IP)&&!self::public_ip($u['host']))throw new \InvalidArgumentException('Private webhook target');if(strtolower($u['host'])==='localhost'||!str_contains($u['host'],'.'))throw new \InvalidArgumentException('Webhook host');return$u;}
 static function public_ip($ip){if(filter_var($ip,FILTER_VALIDATE_IP,FILTER_FLAG_IPV4)&&((ip2long($ip)>>22)===(ip2long('100.64.0.0')>>22)))return false;return filter_var($ip,FILTER_VALIDATE_IP,FILTER_FLAG_IPV4|FILTER_FLAG_NO_PRIV_RANGE|FILTER_FLAG_NO_RES_RANGE)&&!str_starts_with($ip,'100.64.')&&!preg_match('/^(?:0|127|169\.254|192\.0\.0|192\.0\.2|198\.(?:18|19|51\.100)|203\.0\.113|22[4-9]|23[0-9]|24[0-9]|25[0-5])\./',$ip);}
 static function seal($secret){if(!function_exists('openssl_encrypt'))throw new \RuntimeException('Webhook encryption unavailable');$iv=random_bytes(12);$tag='';$cipher=openssl_encrypt($secret,'aes-256-gcm',hash('sha256',wp_salt('auth'),true),OPENSSL_RAW_DATA,$iv,$tag,'robw-forge',16);if($cipher===false)throw new \RuntimeException('Webhook encryption failed');return base64_encode($iv.$tag.$cipher);}
 static function open($box){$raw=base64_decode($box,true);if($raw===false||strlen($raw)<29)throw new \RuntimeException('Webhook key corrupt');$plain=openssl_decrypt(substr($raw,28),'aes-256-gcm',hash('sha256',wp_salt('auth'),true),OPENSSL_RAW_DATA,substr($raw,0,12),substr($raw,12,16),'robw-forge');if($plain===false)throw new \RuntimeException('Webhook key unavailable');return$plain;}
 static function complete($e){foreach($e['deliveries']as$d)if(in_array($d['status'],['pending','sending'],true))return false;return true;}
 static function send($url,$body,$headers){$u=self::validate_url($url);if(self::local()&&$u['scheme']==='http'){$r=wp_remote_post($url,['timeout'=>8,'redirection'=>0,'headers'=>$headers,'body'=>$body,'limit_response_size'=>16384]);if(is_wp_error($r))throw new \RuntimeException('Local webhook transport failure');return wp_remote_retrieve_response_code($r);}if(!function_exists('curl_init')||!defined('CURLOPT_RESOLVE'))throw new \RuntimeException('Pinned TLS webhook transport unavailable');$host=strtolower($u['host']);$ips=filter_var($host,FILTER_VALIDATE_IP)?[$host]:gethostbynamel($host);if(!$ips)throw new \RuntimeException('Webhook DNS failure');foreach($ips as$ip)if(!self::public_ip($ip))throw new \RuntimeException('Webhook private DNS target');$h=curl_init($url);$bytes=0;$hdr=[];foreach($headers as$k=>$v)$hdr[]=$k.': '.$v;curl_setopt_array($h,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>$body,CURLOPT_HTTPHEADER=>$hdr,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_MAXREDIRS=>0,CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_SSL_VERIFYHOST=>2,CURLOPT_CONNECTTIMEOUT=>3,CURLOPT_TIMEOUT=>8,CURLOPT_PROXY=>'',CURLOPT_RESOLVE=>[$host.':443:'.$ips[0]],CURLOPT_WRITEFUNCTION=>function($h,$s)use(&$bytes){$bytes+=strlen($s);return$bytes<=16384?strlen($s):0;}]);$ok=curl_exec($h);$code=(int)curl_getinfo($h,CURLINFO_RESPONSE_CODE);curl_close($h);if($ok===false)throw new \RuntimeException('Webhook bounded TLS transport failure');return$code;}
 static function deliver($id){$token=bin2hex(random_bytes(16));$job=Store::mutate($id,function(&$r)use($token){if(!$r)return null;foreach($r['events']as$eid=>$e)foreach($e['deliveries']as$hid=>$d){if(!isset($r['hooks'][$hid])||$d['attempts']>=5||$d['next']>time()||($d['status']==='sending'&&$d['until']>time())||!in_array($d['status'],['pending','sending'],true))continue;$d['attempts']++;$d['status']='sending';$d['lease']=$token;$d['until']=time()+30;$r['events'][$eid]['deliveries'][$hid]=$d;$payload=$e;unset($payload['deliveries']);return['eid'=>$eid,'hid'=>$hid,'hook'=>$r['hooks'][$hid],'body'=>wp_json_encode($payload)];}return null;});if(!$job)return false;$code=0;$error=null;try{$key=self::open($job['hook']['key']);$code=self::send($job['hook']['url'],$job['body'],['Content-Type'=>'application/json','X-Robw-Event'=>'push','X-Robw-Delivery'=>$job['eid'],'X-Robw-Signature'=>'sha256='.hash_hmac('sha256',$job['body'],$key)]);}catch(\Throwable $e){$error='transport_blocked_or_failed';}Store::mutate($id,function(&$r)use($job,$token,$code,$error){$d=$r['events'][$job['eid']]['deliveries'][$job['hid']]??null;if(!$d||$d['lease']!==$token)return;$d['code']=$code;$d['error']=$error;$d['lease']=null;$d['until']=0;$d['status']=$code>=200&&$code<300?'delivered':($d['attempts']>=5?'failed':'pending');$d['next']=time()+min(3600,30*(2**$d['attempts']));$r['events'][$job['eid']]['deliveries'][$job['hid']]=$d;});return true;}
 static function cron(){foreach(Store::list_ids()as$id)try{self::deliver($id);}catch(\Throwable $e){/* No credentials, request bodies, or signing keys in logs. */}}
}
